sites.find:
int face_offset = 0;
do {
    cRFaceQuad* quad = (cRFaceQuad*)((char*)((Object*)object_cursor)->facequads
        + face_offset);
    cRTexture** texture_slot = &quad->texture_ref;
    if (*texture_slot == old_texture) {
        *texture_slot = new_texture;
    }
    ++face_index;
    face_offset += sizeof(cRFaceQuad);
} while (face_index < ((Object*)object_cursor)->facequad_count);

replacements.text:
int face_offset = 0;
int face_offset_spill = 0;
do {
    face_offset +=
        (int)((Object*)object_cursor)->facequads;
    cRTexture** texture_slot =
        &((cRFaceQuad*)face_offset)->texture_ref;
    if (*texture_slot == old_texture) {
        *texture_slot = new_texture;
    }
    ++face_index;
    face_offset_spill += sizeof(cRFaceQuad);
    face_offset = face_offset_spill;
} while (face_index < ((Object*)object_cursor)->facequad_count);

